var t=`1296-farofa`;var a=`world-1296`;var i=`BR`;var s=`south-america`;var o=4;var r=33;var u={en:`Farofa`,ua:`Фарофа`};var d={en:`Farofa is a dish from Brazil featuring bacon, yellow onion, cassava flour, parsley. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Фарофа, страва кухні країни Бразилія з такими основними складниками: бекон, жовта цибуля, борошно маніоку, петрушка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 11 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 11 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:11,i:[[`bacon`,150,`g`],[`unsalted-butter`,55,`g`],[`yellow-onion`,150,`g`]]},{en:`Toast these ingredients over medium heat for about 16 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 16 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:16,i:[[`cassava-flour`,440,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,28,`g`]]}];var g={slug:t,id:a,country:`BR`,region:s,servings:4,minutes:33,title:u,text:d,steps:l};export{i as country,g as default,a as id,r as minutes,s as region,o as servings,t as slug,l as steps,d as text,u as title};